INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73135, 'spa', 'Totalidad sin excepción', 'Enteramente, completamente, de modo integral, afectando cada parte sin excepción. 1 Tesalonicenses 5:23 emplea este término en la oración de Pablo por una santificación completa: «que seáis santificados por completo». El término subraya la obra de Dios tocando cada dimensión —espíritu, alma, cuerpo— sin dejar área alguna sin transformar. Es santidad integral, no piedad selectiva, lo que Pablo anhela para los creyentes.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73136, 'spa', 'Nombre propio personal', 'Nombre propio de un creyente en Roma a quien Pablo saluda en Romanos 16:15. Olimpas aparece junto a un grupo de nombres, lo que sugiere su pertenencia a una iglesia doméstica romana. No se conoce nada más de este individuo aparte del saludo paulino, pero su inclusión en la lista lo señala como miembro estimado de la comunidad cristiana primitiva, digno del reconocimiento y afecto apostólico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73137, 'spa', 'Higos verdes prematuros', 'Higos inmaduros o prematuros, especialmente los que caen del árbol antes de alcanzar la madurez. Apocalipsis 6:13 emplea este término en su imaginería apocalíptica: las estrellas caen «como la higuera suelta sus higos verdes al ser sacudida por un viento fuerte.» El símil evoca un desprendimiento masivo, innumerables frutos cayendo indefensos bajo una fuerza violenta, una imagen del desmoronamiento cósmico donde los cielos estables se vuelven tan vulnerables como la fruta.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73138, 'spa', 'Enfasis totalizador', 'Adverbio enfatico que significa ''del todo, realmente, en absoluto'', usado para intensificar la afirmacion que modifica. En Mateo 5:34 crea una prohibicion absoluta (''no jureis en absoluto''). En 1 Corintios 5:1 expresa confirmacion escandalizada. En 1 Corintios 6:7 emite un juicio categorico (''del todo una derrota'').');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73139, 'spa', 'Aguacero o chaparrón', 'Tormenta de lluvia intensa, aguacero repentino y a menudo violento, distinto de la lluvia ordinaria. En el uso clásico, ὄμβρος era la tormenta enviada por Zeus (Διὸς ὄμβρος), intensa y a veces destructiva. Jesús lo invoca en Lucas 12:54 como parte de una señal meteorológica: cuando ves una nube levantarse del poniente, dices «viene el aguacero» (ὄμβρος ἔρχεται), y así sucede. El término implica precipitación contundente, no una simple llovizna.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73140, 'spa', 'Conversar, dialogar', 'Mantener una conversación prolongada con alguien, con énfasis en el intercambio personal más que en la oratoria formal. En el camino a Emaús (Lc 24:14-15) describe la conversación íntima de los discípulos. En Hechos 20:11, Pablo conversa toda la noche con los creyentes de Troas. En Hechos 24:26, Félix manda llamar a Pablo repetidamente para dialogar en privado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73141, 'spa', 'Compañía o trato', 'Compañerismo, asociación o el trato habitual que se mantiene con otros, especialmente la interacción social sostenida. En 1 Corintios 15:33 se cita el proverbio griego «las malas compañías corrompen las buenas costumbres», advirtiendo que las amistades moldean el carácter. El término no enfatiza el contacto aislado sino la convivencia continua: los círculos sociales y compañeros cuya influencia, para bien o para mal, forja la vida moral.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73143, 'spa', 'Jurar un juramento o hacer un voto solemne, invocando una autoridad superior com', 'Jurar un juramento o hacer un voto solemne, invocando una autoridad superior como testigo y garante. Aparece en la prohibición de Jesús sobre los juramentos en el Sermón del Monte (Mt 5:34-36), en su crítica de la casuística farisaica (Mt 23:16-22), en la tradición del juramento divino a Abraham (Lc 1:73; Hch 2:30; Heb 6:13; 7:21), en la negación de Pedro bajo juramento (Mt 26:74; Mc 14:71), y en el juramento temerario de Herodes (Mt 14:7; Mc 6:23).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73151, 'spa', 'Unánimemente, de común acuerdo', 'Unánimemente, de común acuerdo. Unanimidad comunal positiva que describe la devoción compartida, la oración y la adoración de la iglesia primitiva. Los creyentes perseveran de común acuerdo en oración (Hch 1:14), se reúnen diariamente para el partimiento del pan (Hch 2:46), oran juntos tras la liberación de Pedro y Juan (Hch 4:24) y se congregan como uno en el Pórtico de Salomón (Hch 5:12). La oración de Pablo en Ro 15:6 extiende esto a glorificar a Dios ''con un mismo sentir.''');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73153, 'spa', 'Ser semejante o asemejarse', 'Ser similar o parecerse a algo, particularmente en manera o característica. Marcos 14:70 emplea este verbo para describir el habla de Pedro: «tu habla es semejante» (o «coincide», «concuerda»). Su acento galileo delató su vínculo con Jesús a pesar de sus negaciones. El verbo capta cómo la semejanza, incluso en algo tan sutil como el dialecto, puede revelar la identidad y la asociación, haciendo imposible el ocultamiento.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73155, 'spa', 'Semejante, similar, parecido', 'Semejante, similar, parecido. Adjetivo de semejanza o analogia que predica parecido entre dos entidades o situaciones. Domina la formula parabolica ὁμοία ἐστὶν ἡ βασιλεία (''el reino es semejante a...'') a lo largo de Mateo 13 y 20, y se extiende a descripciones visionarias en Apocalipsis donde seres celestiales y fenomenos cosmicos se representan mediante analogia (Ap 1:13; 4:3, 7; 9:7, 10, 19). Tambien se usa en comparaciones eticas y en advertencias de Jesus contra la hipocresia (Mt 23:27).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73162, 'spa', 'Comparar o asemejar (activo/deliberativo)', 'Comparar o asemejar (activo/deliberativo): trazar una comparación o analogía de forma activa. ''¿A qué compararé esta generación?'' (Mt 11:16; Lc 7:31) y ''¿Con qué parábola la compararemos?'' (Mr 4:30) emplean este sentido retórico. Es la herramienta del maestro para invitar a los oyentes a una nueva comprensión.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73163, 'spa', 'Ser comparado o asemejado (pasivo)', 'Ser comparado o asemejado (pasivo): ser objeto de una comparación o parábola. Jesús introduce las parábolas del reino con esta forma: ''el reino de los cielos es semejante a un hombre que sembró buena semilla'' (Mt 13:24), o a un rey que ajustaba cuentas (Mt 18:23). La voz pasiva señala que lo comparado está siendo iluminado, no el que compara.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73164, 'spa', 'Llegar a ser semejante o asemejarse (resultativo)', 'Llegar a ser semejante o asemejarse (resultativo): Cristo ''fue hecho semejante a sus hermanos en todo'' (He 2:17), y sin arrepentimiento Israel ''habría sido hecho semejante a Sodoma'' (Ro 9:29). A diferencia de los sentidos 1 y 2, aquí no se trata de ilustración sino de transformación real, o al menos de la amenaza de ella.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73173, 'spa', 'Semejanza, forma', 'Forma visible o representación que se asemeja a algo sin ser idéntica a ello. Teológicamente central en Pablo: los idólatras cambiaron la gloria divina por imágenes ''a semejanza de'' criaturas (Rom 1:23), la muerte reinó sobre quienes pecaron ''a la semejanza de Adán'' (Rom 5:14), y los creyentes se unen a Cristo ''en la semejanza de su muerte'' (Rom 6:5).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73175, 'spa', 'Asimismo, de la misma manera', 'Asimismo, de la misma manera. Adverbio que traza un paralelo explícito entre dos acciones o situaciones, con el sentido de ''del mismo modo.'' Se emplea para encadenar acontecimientos narrativos —los hermanos que se casaron sucesivamente con la misma viuda (Mt 22:26), la declaración de Pedro junto a los demás (Mt 26:35), los sacerdotes que se burlaron al pie de la cruz (Mr 15:31)— y también posee fuerza ética, como en el mandato de Jesús «ve y haz tú lo mismo» (Lc 10:37). En las epístolas estructura la exhortación comunitaria (1 Pe 3:1; 5:5).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73180, 'spa', 'Semejanza divina', 'Parecido o semejanza, especialmente la creación de la humanidad a imagen de Dios. Santiago 3:9 dice que maldecimos a ''personas hechas a semejanza de Dios,'' recordando Génesis 1:26-27. El término enfatiza la similitud: los humanos se asemejan a su Creador y portan la imagen divina. Santiago argumenta que esto hace moralmente intolerable maldecir a los seres humanos, pues denigrar a los portadores de la imagen es atentar contra la semejanza de Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73181, 'spa', 'Confesar, reconocer o admitir abiertamente, ya sea confesando pecados (1 Jn 1', 'Confesar, reconocer o admitir abiertamente, ya sea confesando pecados (1 Jn 1:9), reconociendo una verdad (Jn 1:20, donde el Bautista «confesó y no negó»), o declarando la fe en Cristo (Rom 10:9-10; 1 Jn 4:2-3, 15). Jesús establece la reciprocidad: quien lo confiese ante los hombres, él lo confesará ante el Padre (Mt 10:32; Lc 12:8).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73184, 'spa', 'Prometer, comprometerse o hacer un voto, extendiendo la idea de compromiso verba', 'Prometer, comprometerse o hacer un voto, extendiendo la idea de compromiso verbal desde el reconocimiento presente hacia una obligación futura. Herodes promete con juramento dar a Salomé lo que pida (Mt 14:7), y Esteban relata que Dios «prometió» dar a los descendientes de Abraham la tierra (Hch 7:17).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73188, 'spa', 'Profesar o declarar públicamente, enfatizando la proclamación formal y exterior ', 'Profesar o declarar públicamente, enfatizando la proclamación formal y exterior de creencias o identidad, más que una admisión privada. Jesús advierte que en el día final «declarará» a los inicuos: «Nunca os conocí» (Mt 7:23), y Tito 1:16 condena a quienes «profesan conocer a Dios» pero lo niegan con sus obras.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73198, 'spa', 'Confesión de fe', 'Declaración pública y solemne de fe con compromiso vinculante ante testigos. Timoteo hizo ''la buena confesión delante de muchos testigos'' (1 Tim 6:12), eco de Cristo ante Pilato (1 Tim 6:13). En Hebreos se convierte en término central para la identidad comunitaria cristiana: Jesús es sumo sacerdote ''de nuestra confesión'' (Heb 3:1).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73199, 'spa', 'Por común acuerdo', 'De manera confesada o por acuerdo común; reconocidamente entre todos. En 1 Timoteo 3:16 se introduce un himno cristológico con este adverbio: ''Grande, confesadamente, es el misterio de la piedad.'' El término indica que lo que sigue es universalmente reconocido dentro de la iglesia, doctrina central que todos los creyentes afirman juntos. No es opinión privada de Pablo sino la confesión común de la iglesia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73200, 'spa', 'Del mismo oficio', 'Que comparte el mismo oficio o profesión; ser compañero artesano. Hechos 18:3 señala que Pablo se hospedó con Aquila y Priscila ''porque era del mismo oficio'': todos eran fabricantes de tiendas. Este vínculo ocupacional les proporcionó sustento, compañerismo y una base para el ministerio. El detalle muestra que el oficio de Pablo no era incidental sino parte integral de su estrategia misionera, creando redes a través del trabajo compartido.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73201, 'spa', 'Juntos, en un lugar', 'Juntos, en el mismo lugar o al mismo tiempo, con énfasis en la presencia compartida. En Juan 20:4, dos discípulos corren juntos hacia el sepulcro. Juan 21:2 enumera a los discípulos reunidos junto al mar de Tiberias. Juan 4:36 lo usa figuradamente: sembrador y segador se regocijan juntos. Hechos 2:1 ubica a toda la comunidad en un lugar en Pentecostés.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73202, 'spa', 'De un mismo sentir', 'Tener unidad de mente o ser unánimes, compartiendo los mismos pensamientos y actitudes. En 1 Pedro 3:8 se ordena a los creyentes ser ''de un mismo sentir,'' encabezando un catálogo de virtudes para la vida en comunidad. El término implica armonía en perspectiva y disposición, no uniformidad forzada sino genuino acuerdo que fluye de la fe compartida. Es unidad cognitiva y afectiva que fomenta la paz relacional.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73203, 'spa', 'Sin embargo, no obstante', 'Sin embargo, no obstante, con todo: conjunción que introduce una cláusula concesiva o limitante, matizando lo que precede. Juan 12:42 usa ὅμως para indicar que, a pesar del temor, muchos gobernantes creyeron. 1 Corintios 14:7 matiza la analogía de los instrumentos. Gálatas 3:15 introduce un principio legal con «con todo». El término señala un giro o precisión: lo que sigue permanece vigente a pesar de lo anterior.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73204, 'spa', 'Sueño revelador', 'Sueño durante el dormir que sirve como medio de revelación o advertencia divina. Las seis apariciones neotestamentarias se concentran en Mateo 1-2, donde Dios comunica orientación decisiva mediante sueños: a José sobre la concepción virginal (Matt 1:20), a los Magos para evitar a Herodes (Matt 2:12), y a José para huir a Egipto y regresar (Matt 2:13, 19).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73205, 'spa', 'Asno joven', 'Un burro joven o pollino, particularmente un animal pequeño o inmaduro. Juan 12:14 describe a Jesús hallando ''un asnillo'' para su entrada en Jerusalén, cumpliendo Zacarías 9:9. La forma diminutiva enfatiza el tamaño modesto del animal, reforzando el contraste entre la realeza de Jesús y las expectativas mundanas: viene no sobre un caballo de guerra sino montado en un humilde asno joven, manifestando su reinado a través de la mansedumbre.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73206, 'spa', 'Injuriar, insultar', 'Injuriar, reprochar o acumular abuso verbal contra alguien por hostilidad o desprecio. Se usa para los enemigos que se mofan de Cristo en la cruz (Mt 27:44; Mc 15:32), los perseguidores que insultan a los creyentes (Mt 5:11; Lc 6:22) y los oprobios que cayeron sobre el Mesías (Ro 15:3, citando Sal 69:9). El español ''injuriar/insultar'' capta fielmente el carácter hostil y degradante de estos ataques.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73209, 'spa', 'Reprender, censurar', 'Reprender o censurar con autoridad, expresando fuerte desaprobación hacia quienes deberían comprender mejor. Jesús ''comenzó a reprochar'' a las ciudades donde se realizaron sus obras poderosas (Mt 11:20), y ''reprochó'' a los once por su obstinada incredulidad tras la resurrección (Mc 16:14). El español ''reprochar'' desplaza el registro de la hostilidad externa hacia la censura correctiva interna: la reprensión proviene de una autoridad legítima.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73212, 'spa', 'Reprochar al dar', 'Reprochar en el sentido de recriminar o avergonzar al receptor, usado únicamente en negación en Santiago 1:5, donde Dios da sabiduría ''sin reprochar'' (μὴ ὀνειδίζοντος). Este sentido preserva el significado central de echar en cara, pero lo aplica a la relación donante-receptor: a diferencia de los benefactores humanos que recuerdan su generosidad, Dios da sin hacer que quien pide se sienta menospreciado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73215, 'spa', 'Oprobio, afrenta', 'Oprobio o afrenta: vergüenza pública, insulto o vituperio soportado generalmente por fidelidad a Dios. En Romanos 15:3, Cristo carga con los oprobios destinados a Dios (citando Sal 69:9). Hebreos desarrolla una teología del oprobio: algo que se soporta públicamente (10:33), se elige deliberadamente como hizo Moisés (11:26) y se abraza como marca de identificación con Jesús «fuera del campamento» (13:13).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73216, 'spa', 'Reproche o deshonra pública', 'Reproche público, deshonra o vergüenza, en particular el estigma social vinculado a un supuesto desfavor divino. Lucas 1:25 registra el gozo de Elisabet porque Dios le ha «quitado su afrenta»: la vergüenza de la esterilidad que cargó durante años. En su contexto cultural, no tener hijos sugería juicio divino, convirtiéndola en objeto de lástima y desprecio. El embarazo milagroso la reivindicó públicamente, borrando el reproche.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73220, 'spa', 'Recibir beneficio o provecho', 'Recibir beneficio o provecho de alguien, especialmente en sentido relacional o práctico. Filemón 20 emplea este verbo en la súplica de Pablo: «que yo tenga beneficio de ti en el Señor.» El verbo juega con el nombre de Onésimo («Útil») y solicita a Filemón un beneficio tangible: la acogida generosa del esclavo que regresa. Pablo busca tanto gozo personal como reconciliación práctica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73221, 'spa', 'nombre, título, reputación', 'Designación personal, título o etiqueta identificativa aplicada a una persona, lugar o ser divino, que se extiende naturalmente a la reputación y la autoridad delegada. La construcción «en el nombre de» (ἐν τῷ ὀνόματι) marca agencia, invocación o apelación a la autoridad de otro. Todas las traducciones principales convergen en un solo equivalente nuclear (spa «nombre», fra «nom», deu «Name»), confirmándolo como sentido unificado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73225, 'spa', 'Nombrar, llamar por nombre', 'Nombrar, llamar por nombre. Dar un nombre a alguien o algo, o ser llamado y conocido por un nombre o titulo. El nombramiento activo ocurre cuando Jesus designa a los apostoles (Lucas 6:13-14, Marcos 3:14); el ser nombrado pasivamente describe reputaciones y titulos que trascienden la era presente (Efesios 1:21, todo nombre que se nombra; Efesios 3:15, toda familia nombrada por el Padre). Tambien abarca invocar un nombre en exorcismos (Hechos 19:13), confesar un nombre y la prohibicion de nombrar ciertos pecados entre los santos (Efesios 5:3).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73234, 'spa', 'Asno, animal de carga', 'Asno o burro, animal de carga domesticado en el antiguo Cercano Oriente. Los usos neotestamentarios se agrupan en dos contextos: la entrada triunfal (Mt 21:2, 5, 7; Jn 12:15), donde Jesús entra en Jerusalén sobre un asno cumpliendo Zacarías 9:9, y una controversia sabática (Lc 13:15), donde desatar al asno para darle agua es sentido común.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73235, 'spa', 'Verdaderamente, realmente', 'Verdaderamente, realmente. Adverbio que significa ''verdaderamente'', ''realmente'', ''de hecho'', usado para afirmar la realidad genuina de una declaracion o condicion. Confirma la identidad profetica (Marcos 11:32, Juan era verdaderamente profeta), declara verdades cristologicas (Lucas 23:47, este era verdaderamente un hombre justo; Lucas 24:34, el Senor verdaderamente ha resucitado), y distingue el estatus autentico de la mera apariencia (1 Timoteo 5:3,5,16, verdaderamente viudas; 1 Timoteo 6:19, verdaderamente vida).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73238, 'spa', 'Vino agrio, vinagre', 'Vino barato y ácido (latín posca) ofrecido a Jesús durante la crucifixión, atestiguado en los cuatro Evangelios. Su ofrecimiento conlleva matices ambiguos: a veces burla (Lucas 23:36), a veces gesto mínimo de alivio (Juan 19:29-30, donde Jesús lo recibe y dice ''Consumado es''). La esponja empapada se ha convertido en imagen icónica de la Pasión.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73240, 'spa', 'Agudo, afilado', 'Agudo, afilado — que describe una hoja, espada o instrumento cortante con un filo fino y penetrante. Las siete apariciones con este significado se encuentran todas en Apocalipsis: la ''espada aguda de dos filos'' que sale de la boca de Cristo (Ap 1:16; 2:12), la ''hoz afilada'' sostenida por quien era semejante al Hijo del Hombre y por los ángeles segadores (Ap 14:14, 17, 18), y la hoz afilada mencionada en Ap 14:18 y 19:15.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73241, 'spa', 'Veloz, rápido', 'Veloz, rápido, ligero — que describe velocidad de movimiento en lugar del filo de una hoja. La única aparición neotestamentaria con este sentido es Romanos 3:15, donde Pablo cita Isaías 59:7 en su cadena de testimonios veterotestamentarios sobre la pecaminosidad universal: ''veloces son sus pies para derramar sangre''. El español pasa de ''afilada'' (agudo) a ''veloces'' (rápido), marcando con claridad la frontera semántica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73243, 'spa', 'Detrás, por detrás', 'En la parte posterior o desde atrás de una persona u objeto, describiendo posición espacial o dirección de aproximación. El término posee gran viveza narrativa en los Evangelios: la mujer con hemorragia se acerca a Jesús ''por detrás'' (Mt 9:20; Mr 5:27; Lc 8:44), transmitiendo simultáneamente el estigma social y la fe desesperada. En Apocalipsis 4:6 las criaturas vivientes se describen como cubiertas de ojos por delante y ''por detrás''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73246, 'spa', 'Después, detrás, atrás', 'Después, detrás, atrás. Adverbio y preposición impropia que expresa posición espacial detrás, secuencia temporal después o movimiento direccional hacia atrás. Tres patrones dominantes en el Nuevo Testamento: la llamada al discipulado δεῦτε ὀπίσω μου (''venid en pos de mí,'' Mt 4:19; 16:24; Mr 8:34), que establece el seguir como esencia del discipulado; la fórmula de subordinación del Bautista ὁ ὀπίσω μου ἐρχόμενος (''el que viene después de mí,'' Mt 3:11; Jn 1:15, 27); y la advertencia contra mirar atrás (εἰς τὰ ὀπίσω), que evoca a la mujer de Lot: «nadie que pone la mano en el arado y mira hacia atrás es apto para el reino» (Lc 9:62; cf. 17:31).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73252, 'spa', 'Armarse o equiparse', 'Armarse o equiparse, especialmente con armas para la guerra, aquí usado metafóricamente para la preparación mental y espiritual. 1 Pedro 4:1 ordena a los creyentes «armaos con la misma disposición» que tuvo Cristo ante el sufrimiento. La metáfora militar se transforma en consejo espiritual: equipar deliberadamente la mente como un soldado que se arma para la batalla, preparándose mental y espiritualmente para soportar la adversidad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73253, 'spa', 'Armas e instrumentos', 'Armas, instrumentos o herramientas, ya sea equipo militar literal o herramientas morales y espirituales figuradas. En su único uso literal, el grupo que arresta a Jesús lleva «armas» a Getsemaní (Juan 18:3). Pablo desarrolla la metáfora: los creyentes deben ofrecer sus miembros como «instrumentos de justicia» (Rom 6:13) y revestirse de «las armas de la luz» (Rom 13:12).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73254, 'spa', 'De qué clase', 'Adjetivo correlativo-relativo que dirige la atención al carácter de una persona o cosa. En 1 Corintios 3:13, el fuego escatológico revela ὁποῖον, qué clase de obra ha construido cada uno. Pablo lo usa en Gálatas 2:6 para desestimar el estatus de los apóstoles «columnas». En 1 Tesalonicenses 1:9 evoca la calidad de la acogida al evangelio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73255, 'spa', 'donde', 'Adverbio relativo de lugar que significa «donde» o «dondequiera que», situando una acción o un estado en referencia a un lugar previamente mencionado o implícito. Frecuente en la enseñanza de Jesús para establecer conexiones espacio-teológicas: donde está vuestro tesoro (Mt 6:19-21), donde esté el cuerpo (Mt 24:28), donde yo estoy (Jn 14:3). Con ἄν o ἐάν forma el generalizador «dondequiera que» (Mc 6:56; 14:9).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73258, 'spa', 'Aparecer o manifestarse', 'Aparecer o ser visto, especialmente en manifestación reveladora o sobrenatural. Hechos 1:3 describe a Jesús «apareciéndoseles durante cuarenta días» después de la resurrección. El término enfatiza apariciones visibles y tangibles, no visiones interiores, sino encuentros objetivos donde el Cristo resucitado se presentó a sí mismo. La construcción pasiva puede implicar revelación divina: Jesús se dejó ver, manifestando su condición de resucitado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73259, 'spa', 'Vision divina', 'Vision o aparicion sobrenatural mediante la cual Dios comunica a traves de lo que se ve. La mudez de Zacarias confirma que ha recibido una vision en el templo (Lc 1:22). Las mujeres reportan una vision de angeles anunciando la resurreccion (Lc 24:23). Pablo describe su encuentro en Damasco como una ''vision celestial'' irresistible (Hch 26:19).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73260, 'spa', 'Asado o cocido al fuego', 'Asado o cocido a la brasa, describiendo alimento preparado sobre calor directo. Lucas 24:42 señala que al Jesús resucitado le dieron «parte de un pez asado», el cual comió en presencia de los discípulos. Este detalle culinario mundano cumple un propósito teológico profundo: que Jesús coma alimento ordinario y preparado prueba la realidad física de su cuerpo de resurrección. No es un fantasma sino un ser corpóreo, capaz de actividad humana normal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73261, 'spa', 'Fruto maduro o cosecha', 'Fruto maduro o producción de la temporada de cosecha, que simboliza abundancia y lujo. Apocalipsis 18:14 lamenta la pérdida de Babilonia: «El fruto maduro que tu alma ansiaba se fue de ti». En contexto, representa riqueza material e indulgencia sensual: frutos selectos que simbolizan prosperidad económica. La imagen del fruto anhelado que desaparece de repente capta la totalidad del juicio divino.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73262, 'spa', 'para que, a fin de que', 'Conjunción de propósito: «para que, a fin de que». Introduce el resultado pretendido o la meta de una acción. Aparece en prácticamente todos los géneros del Nuevo Testamento. El español «para que» y el francés «afin que» convergen unánimemente en el sentido final (Mt 2:8; Mt 5:16). Es con diferencia el uso dominante, con unas 50 apariciones.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73263, 'spa', 'cómo (interrogativo)', 'Adverbio interrogativo de modo: «cómo, de qué manera». Conserva la fuerza interrogativa del griego clásico, preguntando por el medio o el método. El español «cómo» y el cambio respecto a las glosas de propósito confirman este sentido diferenciado. Aparece en contextos deliberativos donde los adversarios planean contra Jesús (Mt 22:15; Mc 3:6; Lc 24:20).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73266, 'spa', 'Visión sobrenatural concedida por Dios, generalmente durante la oración, el sueñ', 'Visión sobrenatural concedida por Dios, generalmente durante la oración, el sueño o un estado de éxtasis, que transmite revelación o instrucción divina. Es el uso dominante en el Nuevo Testamento, presente a lo largo de Hechos como recurso narrativo central: Ananías ve una visión que lo dirige a Saulo (Hch 9:10), Cornelio recibe instrucción angélica «en una visión» (Hch 10:3), y Pablo es dirigido a Macedonia por una visión nocturna (Hch 16:9). En el Monte de la Transfiguración, Jesús llama «visión» a la revelación deslumbrante de su gloria (Mt 17:9).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73267, 'spa', 'Un espectáculo o fenómeno visual notable que capta la atención, con énfasis en l', 'Un espectáculo o fenómeno visual notable que capta la atención, con énfasis en lo que se percibe visualmente más que en un mensaje revelador. En Hechos 7:31, Moisés «se maravilló ante la visión» de la zarza ardiente que no se consumía. Aunque sigue siendo sobrenatural en su origen, el enfoque aquí recae sobre el fenómeno visual asombroso en sí mismo, no sobre una comunicación verbal o instrucción.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73268, 'spa', 'Vision sobrenatural', 'Vision o percepcion sobrenatural: una experiencia visual concedida divinamente. En Hechos 2:17 Pedro cita la profecia de Joel de que los jovenes veran ''visiones'' (ὁράσεις), senalando un derramamiento escatologico de vision profetica. La forma plural subraya una experiencia profetica repetida o comunitaria propia de la era mesianica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73269, 'spa', 'Visible o perceptible', 'Visible o perceptible a la vista, describiendo la creación material que puede ser observada. Colosenses 1:16 emplea este término para categorizar la creación: Cristo hizo «lo visible y lo invisible», es decir, el mundo físico que vemos y las realidades espirituales más allá de nuestra vista (poderes angélicos, autoridades espirituales). La distinción afirma la soberanía universal de Cristo sobre los ámbitos material e inmaterial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73270, 'spa', '!he aqui! (exclamativo)', 'La interjeccion exclamativa idou, que significa ''!he aqui!'' o ''!mira!'': 256 ocurrencias que la convierten en uno de los marcadores discursivos mas frecuentes del Nuevo Testamento. Funciona como foco retorico: ''He aqui, una virgen concebira'' (Mt 1:23), ''He aqui, yo estoy con vosotros todos los dias'' (Mt 28:20). No es una orden literal de mirar, sino un recurso de intensificacion dramatica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73272, 'spa', 'ver, percibir visualmente', 'Ver con los ojos, el acto basico de percepcion visual: 419 ocurrencias en todo contexto narrativo del Nuevo Testamento. Los magos ''vieron'' la estrella (Mt 2:10), Jesus ''vio'' las multitudes (Mt 5:1), los discipulos ''vieron'' a Jesus caminando sobre el mar (Mt 14:26). El participio aoristo idon (''habiendo visto'') funciona como recurso de transicion narrativa sumamente frecuente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73295, 'spa', 'aparecer, hacerse visible', 'El sentido pasivo: aparecer, hacerse visible, ser visto: 4 ocurrencias de especial densidad teologica. Moises y Elias ''aparecieron'' en la Transfiguracion (Lc 9:31), lenguas de fuego ''aparecieron'' en Pentecostes (Hch 2:3). Es el vocabulario propio de la teofania y la manifestacion divina, donde la voz pasiva senala que la iniciativa de ser visto proviene de Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73298, 'spa', 'percibir, comprender', 'Percibir mentalmente, comprender o captar con la mente en lugar de con los ojos: 3 ocurrencias, todas vinculadas a la cadena de citas de Isaias 6:9-10. ''Viendo vereis y no percibireis'' (Mt 13:14; Mc 4:12; Hch 28:26) emplea horao en contraste deliberado con la vision fisica para denotar comprension espiritual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73321, 'spa', 'mirar, contemplar', 'Una unica ocurrencia en Jn 19:37, citando Zacarias 12:10: ''Miraran al que traspasaron.'' El verbo opsontai (''miraran'') conlleva el peso de la contemplacion profetica: no un ver casual, sino una mirada intensa y penitencial dirigida al Mesias crucificado. El espanol ''mirar'' capta esta direccionalidad e intensidad frente al simple ''ver.''');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73322, 'spa', 'Ira, enojo (sentido general)', 'Ira, enojo (sentido general). Cólera profunda e intensa que abarca tanto la ira judicial asentada de Dios como la respuesta emocional apasionada del ser humano. El sentido divino predomina: Juan el Bautista advierte de «la ira venidera» (Mt 3:7), Pablo habla de ser «salvos de la ira» (Ro 5:9) y Apocalipsis presenta «el gran día de su ira» (Ap 6:17). Marcos 3:5 aporta la dimensión humana, donde Jesús mira «con enojo.»');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73328, 'spa', 'Enojarse, airarse', 'Enojarse o ser movido a ira, expresando la experiencia pasiva del enojo en vez de su instigación activa. En las parábolas de Jesús describe la furia de un rey ante quienes rechazaron su invitación (Mt 22:7) y la indignación de un amo ante huéspedes desagradecidos (Lc 14:21). El hermano mayor del hijo pródigo ''se enojó'' y se negó a entrar (Lc 15:28). En la instrucción ética, Efesios 4:26 permite la emoción inicial de la ira pero prohíbe que se convierta en pecado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73334, 'spa', 'Iracundo o colérico', 'Propenso a la ira o de genio vivo, describiendo a alguien cuyo temperamento se inflama fácilmente. Tito 1:7 excluye al «iracundo» del liderazgo eclesial. Pablo requiere que los obispos sean sobrios y dueños de sí mismos, no dados a arrebatos de cólera. El término denota un defecto de carácter: no indignación justa sino un temperamento irascible que estalla impulsivamente, incompatible con el ministerio pastoral.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73336, 'spa', 'Desear, aspirar a', 'Extenderse hacia algo, desear o aspirar a una meta, ya sea noble o indigna. 1 Timoteo 3:1 elogia al que aspira al liderazgo eclesial. 1 Timoteo 6:10 advierte que la codicia de riquezas extravía. Hebreos 11:16 describe a los fieles anhelando una patria celestial. El griego ὀρέγω significa literalmente «estirar hacia» y en sentido figurado abarca el anhelo y la ambición.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73338, 'spa', 'Deseo o anhelo intenso', 'Deseo, apetito o anhelo intenso, particularmente de gratificación física o sensual. Romanos 1:27 emplea este término para el deseo sexual ilícito: hombres «consumidos de deseo unos por otros», abandonando las relaciones naturales. El vocablo denota una intensidad ardiente, no una mera preferencia sino un ansia abrumadora. En contexto, es un apetito desordenado que contradice el propósito creacional de Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73339, 'spa', 'Conducirse con rectitud', 'La única aparición en Gálatas 2:14 emplea la metáfora de caminar por un sendero recto para describir la coherencia con la verdad del evangelio. La pregunta retórica de Pablo, «no andan rectamente», señala la brecha entre lo que se cree y cómo se actúa, convirtiendo este raro verbo en una crítica incisiva de la inconsistencia moral cuando la presión social tienta al compromiso.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73341, 'spa', 'Trazar rectamente', 'En 2 Timoteo 2:15, la frase participial ''que traza rectamente la palabra de verdad'' exige una interpretación y enseñanza cuidadosa y precisa de las Escrituras. La metáfora proviene de oficios que requieren precisión —construcción de caminos, cantería o agricultura— para subrayar que la palabra de Dios demanda un manejo fiel, no distorsión por conveniencia o preferencia personal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73342, 'spa', 'Madrugar con devoción', 'Lucas 21:38 describe a las multitudes del templo que ''madrugaban'' para escuchar a Jesús, destacando su determinación a pesar de la hora temprana. Esta acción habitual (en tiempo imperfecto) refleja una devoción sostenida: día tras día venían al alba, sin querer perderse sus palabras aunque ello significara sacrificar sueño y comodidad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73343, 'spa', 'De madrugada', 'Lucas 24:22 usa este adjetivo para describir a las mujeres del grupo que llegaron al sepulcro de Jesús al alba. El momento intensifica el descubrimiento dramático: al primer rayo del día, cuando las dolientes solían visitar las tumbas, estas mujeres hallaron no un cadáver sino un anuncio angélico. La hora temprana subraya su devoción y prepara el escenario para la revelación de la resurrección.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73344, 'spa', 'Alba, amanecer', 'Alba, amanecer o madrugada: el momento justo antes o al salir el sol, cuando la oscuridad da paso a la luz. Lucas 24:1 sitúa la llegada de las mujeres al sepulcro al ὄρθρος (muy de madrugada). Juan 8:2 ubica a Jesús en el templo «al alba». Hechos 5:21 menciona a los apóstoles enseñando al despuntar el día. El griego ὄρθρος denota específicamente el período previo al amanecer o el amanecer mismo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73345, 'spa', 'Correcta o rectamente', 'De manera correcta, recta o apropiada, indicando que el habla o la accion se ajusta a la verdad o al funcionamiento debido. En Lucas 7:43 Jesus dice a Simon ''Has juzgado correctamente,'' y en Lucas 20:21 reconocen que ensena ''rectamente.'' Marcos 7:35 extiende el sentido al habla fisica restaurada a su funcion recta.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73346, 'spa', 'Designar a una persona', 'Designar o nombrar a una persona para un cargo o función particular, enfatizando la autoridad detrás de la selección. En Hechos 10:42, Jesús es quien ha sido ''designado por Dios como juez de vivos y muertos''. El español ''designado'' resalta el carácter oficial y comisionador de este sentido, distinguiéndolo del mero acto de determinar acontecimientos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73347, 'spa', 'Determinar, ordenar', 'Determinar, fijar o preordenar acontecimientos, tiempos o acciones según un consejo deliberado, ya sea divino o humano. El plan predeterminado de Dios está en vista en Lucas 22:22 y Hechos 2:23; la toma de decisiones humana aparece en Hechos 11:29. El español ''determinado/designó'' refleja la fuerza deliberada y delimitadora de la palabra a lo largo de Hechos 17:26 y 17:31.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73349, 'spa', 'Declarar públicamente', 'Declarar o señalar públicamente con una designación autoritativa. Romanos 1:4 constituye un caso único: Jesús fue ''declarado Hijo de Dios con poder por la resurrección de entre los muertos''. La evidencia multilingüe es reveladora: el español pasa a ''declarado'' en vez de ''determinado'', sugiriendo que el énfasis recae en la proclamación pública más que en la predeterminación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73354, 'spa', 'Región geográfica definida o distrito territorial, generalmente en plural, que d', 'Región geográfica definida o distrito territorial, generalmente en plural, que describe los confines de un lugar con nombre propio. Traza los desplazamientos de Jesús: Tiro y Sidón (Mt 15:22; Mc 7:24), Gadara (Mt 8:34), Judea (Mt 19:1). En el griego clásico servía como diminutivo de ὅρος (''mojón fronterizo''), aunque en el período koiné había perdido toda fuerza diminutiva. Las traducciones en distintas lenguas confirman un único sentido espacial indiferenciado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73358, 'spa', 'Conjurar, hacer jurar', 'Poner bajo juramento solemne o conjurar invocando un nombre sagrado. Las tres apariciones en el Nuevo Testamento muestran contextos distintos: un demonio que se dirige a Jesús (Marcos 5:7), exorcistas ambulantes que invocan el nombre de Jesús (Hechos 19:13) y Pablo que encarga solemnemente a los creyentes (1 Tesalonicenses 5:27). El verbo implica compeler mediante invocación divina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73359, 'spa', 'Juramento, promesa solemne', 'Juramento, promesa solemne. Declaracion solemne jurada o voto, que a menudo invoca a Dios como garante, y que obliga al jurante a cumplir una promesa. Abarca juramentos humanos: el voto precipitado de Herodes en el banquete (Mateo 14:7,9), la tradicion veterotestamentaria de cumplir los juramentos al Senor (Mateo 5:33), y la negacion de Pedro bajo juramento (Mateo 26:72 par.); y juramentos divinos: la promesa pactual de Dios a Abraham (Lucas 1:73; Hechos 2:30) y el argumento teologico de que un juramento es la confirmacion definitiva (Hebreos 6:16-17).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73362, 'spa', 'Juramento solemne', 'El acto solemne de jurar: una declaracion formal y vinculante respaldada por la autoridad divina. Las cuatro ocurrencias se concentran en Hebreos 7, donde el autor contrasta el sacerdocio levitico (establecido sin juramento) con el de Cristo (instituido por la palabra jurada de Dios, citando el Salmo 110:4). El termino enfatiza la naturaleza performativa y pactual del compromiso divino.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73363, 'spa', 'Precipitarse violentamente', 'Lanzarse o arremeter con violencia: moverse con fuerza subita e impetuosa, frecuentemente como turba o estampida. La raiz ὁρμή (impulso, acometida) confiere un sentido de empuje irresistible. Tres de cinco ocurrencias describen a los cerdos endemoniados precipitandose al mar (Mt 8:32; Mc 5:13; Lc 8:33), una de las escenas mas vividas de los Evangelios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73365, 'spa', 'Ímpetu devastador', 'Apocalipsis 18:21 presenta a un ángel arrojando una gran piedra de molino al mar ''con ímpetu,'' usando este sustantivo para enfatizar la finalidad y la fuerza de la caída de Babilonia. La imagen combina peso (una piedra de molino), acción (lanzamiento) e impulso (arrastre violento) para comunicar que el juicio, una vez iniciado, no puede detenerse ni suavizarse: se desploma con una plenitud devastadora.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73366, 'spa', 'Ave, pájaro', 'Ave o pájaro: término genérico para criaturas aladas. Las tres apariciones neotestamentarias se encuentran en la imaginería apocalíptica de Apocalipsis, donde las aves funcionan como carroñeras en escenas de juicio divino. En el uso clásico, τὰ ὄρνεα podía referirse también a un mercado de aves, pero el uso bíblico es literal: aves como agentes de la retribución divina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73368, 'spa', 'Límites designados', 'Hechos 17:26 describe a Dios determinando ''los límites de su habitación,'' refiriéndose a los tiempos señalados y las fronteras territoriales de las naciones. El discurso de Pablo en el Areópago emplea este término para contrarrestar nociones de distribución humana aleatoria, afirmando que la geografía y la cronología sirven al propósito de Dios: que los pueblos le busquen. Los límites no son arbitrarios sino pedagógicos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73369, 'spa', 'monte, montaña', 'Monte o cerro que designa una elevación física y que frecuentemente sirve de escenario para la revelación divina y eventos decisivos. Jesús es tentado en un monte alto (Mt 4:8), enseña desde una ladera (Mt 5:1), se transfigura en otro (Mt 17:1) y pronuncia su discurso escatológico en el Monte de los Olivos (Mt 24:3). La alegoría paulina del Sinaí frente a la Jerusalén de arriba (Gá 4:24-25) extiende el simbolismo montañoso al plano teológico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73371, 'spa', 'Cavar, excavar', 'La evidencia interlingüística confirma el sentido básico de cavar o excavar: español «cavó», francés «creuser», alemán «graben». El léxico remonta este verbo al griego homérico. Dos ocurrencias corresponden a la parábola de la viña donde el dueño «cavó» un lagar (Mt 21:33; Mr 12:1), y una describe al siervo que «cavó» en la tierra para enterrar el dinero de su amo (Mt 25:18).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73373, 'spa', 'Bailar, danzar', 'Bailar o danzar: movimiento corporal ritmico y expresivo, ya sea en celebracion, entretenimiento o como metafora del gozo receptivo. En la parabola de los ninos en el mercado (Mt 11:17; Lc 7:32), la danza es la respuesta gozosa esperada ante la musica, en contraste con el lamento. En el banquete de Herodes (Mt 14:6; Mc 6:22), el mismo verbo describe una actuacion con consecuencias mortales.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73375, 'spa', 'quienquiera/cualquiera (indef.)', 'El pronombre relativo indefinido o generalizador: ''quienquiera que,'' ''cualquier cosa que,'' ''lo que'': aproximadamente 232 ocurrencias, tipicamente con las particulas an o ean para senalar alcance universal o condicional. En Mt 10:27: ''lo que os digo en tinieblas, decidlo en la luz''; en Mt 16:19: ''todo lo que ateis en la tierra.'' El espanol oscila entre ''lo que'' y ''cualquier cosa que.''');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73376, 'spa', 'pron. relativo quien/que/cual', 'El pronombre relativo definido estandar que introduce una clausula con antecedente especifico: ''quien,'' ''que,'' ''cual,'' ''cuyo,'' ''a quien,'' ''del cual'': aproximadamente 1.149 ocurrencias, el sentido ampliamente dominante. Cubre todas las flexiones de caso, genero y numero, y abarca todos los generos literarios del Nuevo Testamento. En Mt 2:16 Herodes pregunta por el tiempo ''en que'' aparecio la estrella.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73407, 'spa', 'uno/otro, unos/otros (correlat.)', 'El uso correlativo-distributivo en el patron hos men...hos de, que significa ''uno...otro'' o ''unos...otros'': aproximadamente 30 ocurrencias. Esta construccion reutiliza el pronombre relativo como indefinido, repartiendo un grupo en subconjuntos. La Parabola del Sembrador lo ilustra claramente: ''una [semilla] cayo junto al camino...otra en pedregales...otra entre espinos...otra en buena tierra'' (Mt 13:4-8).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73417, 'spa', 'donde (locativo)', 'Un uso locativo o cuasiadverbial que significa ''donde'': solo 4 ocurrencias, representando una extension espacial del paradigma relativo. En Lc 4:17 Jesus abre el rollo ''donde'' (hou) estaba escrito sobre el; en Lc 23:53 el sepulcro ''donde'' nadie habia sido puesto aun; en Ro 9:26 ''en el lugar donde'' se les dijo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73443, 'spa', 'Cuantas veces', 'Las traducciones multilingües captan uniformemente el aspecto de frecuencia: español «cuantas veces», francés «autant de fois», alemán «sooft». El léxico señala que es correlativo de «tantas veces» (τοσσάκι) en el uso clásico. En 1 Co 11:25-26, Pablo enfatiza que cada celebración de la Cena del Señor es una proclamación, mientras que Ap 11:6 subraya el poder reiterado de los testigos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73444, 'spa', 'El Santo', 'Uso sustantivado y adjetival que significa «Santo» o «santo, devoto, piadoso», aplicado tanto cristológicamente como éticamente. Como título cristológico aparece en el sermón de Pedro en Pentecostés (Hechos 2:27) y en el discurso de Pablo en Antioquía de Pisidia (Hechos 13:35), ambos citando el Salmo 16:10 LXX para argumentar que Dios no permitió que su «Santo» sufriera corrupción. Aplicado al carácter humano, describe al creyente devoto y fiel.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73446, 'spa', 'Cosas santas', 'El neutro plural τὰ ὅσια usado como sustantivo para significar «las cosas santas» o «las misericordias fieles», refiriéndose a las promesas sagradas del pacto de Dios. Este sentido aparece en Hechos 13:34, donde Pablo declara que Dios resucitó a Jesús para cumplir «las cosas santas de David, las fieles», aludiendo a las promesas de 2 Samuel 7 e Isaías 55:3 LXX.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73448, 'spa', 'Conducta devota', 'En 1 Tesalonicenses 2:10, Pablo apela a los tesalonicenses como testigos de cuán devotamente se condujo entre ellos. El adverbio aparece en una tríada —«santa, justa e irreprensiblemente»— cada una resaltando una faceta distinta de integridad. «Santamente» señala la orientación de Pablo hacia Dios, su determinación consciente de honrar las normas divinas en su ministerio y relaciones.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73449, 'spa', 'Olor, fragancia, aroma', 'Olor, fragancia o aroma, empleado en el NT para olores agradables, especialmente dentro de la metáfora cúltica del sacrificio aceptable ante Dios. Juan 12:3 registra la fragancia literal del nardo en Betania. Pablo desarrolla la imagen: la proclamación apostólica es «aroma de Cristo» (2 Cor 2:14-16), Cristo mismo «ofrenda fragante» (Ef 5:2) y el regalo filipense «olor suave» (Fil 4:18).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73451, 'spa', 'cuanto, lo que (cosas)', 'Uso neutro o femenino plural referido a cosas, eventos o cantidades: «todo lo que, cuanto, cuantas cosas». Reúne una clase entera de objetos o acciones. Pasajes clave incluyen Mt 7:12 («todo lo que queráis que los hombres hagan con vosotros»), Mt 18:18 («todo lo que atéis en la tierra») y Fil 4:8 («todo lo que es verdadero»). El español «cuantas cosas» resulta particularmente expresivo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73452, 'spa', 'cuantos, todos los que', 'Uso masculino plural referido a personas: «cuantos, todos los que, quienquiera que». Señala personas dentro de un grupo. Prominente en relatos de sanación (Mt 14:36, Mc 6:56: «todos los que le tocaban quedaban sanos») y en los sumarios de conversión de Hechos (Hch 2:39, 4:6). Este uso personal porta una fuerza inclusiva que delimita los contornos de la comunidad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73454, 'spa', 'en cuanto (proporcional)', 'Uso proporcional o comparativo que indica grado o extensión escalar: «en cuanto, en la medida en que, en proporción a». Se encuentra en 14 pasajes, incluido el crucial Mt 25:40 («en cuanto lo hicisteis a uno de estos mis hermanos más pequeños»), donde ὅσος establece la equivalencia proporcional entre el servicio al humilde y el servicio a Cristo. Mc 7:36 lo emplea de modo sorprendente: «cuanto más les mandaba, tanto más lo divulgaban».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73457, 'spa', 'cuánto (exclamativo)', 'Uso exclamativo o retórico que expresa magnitud: «¡cuánto!, ¡cuántas cosas!, ¡qué grandes cosas!». Concentrado en Marcos, donde al endemoniado sanado se le dice que declare ὅσα («cuántas cosas») el Señor ha hecho por él (Mc 5:19-20). Este sentido pasa de la correlación a la declaración enfática, maravillándose ante la magnitud de la acción divina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73462, 'spa', 'mientras, en tanto que', 'Uso temporal que marca duración: «mientras, en tanto que, todo el tiempo que». Cinco ocurrencias, típicamente en la frase ἐφ'' ὅσον («por cuanto tiempo»), incluyendo Ro 7:1 («la ley se enseñorea del hombre entre tanto que vive»), 1 Co 7:39 («ligada mientras su marido vive») y Gá 4:1 («entre tanto que el heredero es niño»). El español «mientras» y «en tanto que» traducen bien la extensión temporal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73481, 'spa', 'Hueso, huesos', 'Hueso o huesos: el material esqueletico duro del cuerpo, empleado tanto en sentido literal como en formas figuradas de gran peso teologico. En Lc 24:39, Jesus resucitado invita a los discipulos a palpar sus huesos como prueba de su resurreccion fisica. Mt 23:27 usa los huesos como simbolo de muerte e impureza oculta tras la apariencia exterior. Jn 19:36 cumple la tipologia del cordero pascual, y Ef 5:30 evoca la union conyugal de Genesis.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73482, 'spa', 'quien, el cual', 'Función estándar de pronombre relativo con el significado de «quien», «el cual» o «que», introduciendo cláusulas que identifican o describen un referente específico. Es el uso dominante en el NT (123 de 140 ocurrencias). Las traducciones interlingüísticas convergen en formas relativas simples: spa «quienes / los cuales», fra «qui», deu «die». Se encuentra en contextos narrativos y didácticos, como Mt 7:15 (falsos profetas «que vienen a vosotros»).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73485, 'spa', 'cualquiera que, quienquiera', 'Relativo generalizante o indefinido que significa «cualquiera que», «quienquiera que» o «todo aquel que», donde la cláusula porta fuerza condicional o universal. El español pasa elocuentemente a «cualquiera que» y «el que», marcando el alcance abierto. Este uso se concentra en la enseñanza ética de Jesús: «cualquiera que te hiera en la mejilla derecha» (Mt 5:39), «cualquiera que te obligue a llevar carga por una milla» (Mt 5:41).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73492, 'spa', 'Sentido del olfato', 'En 1 Corintios 12:17, Pablo pregunta: «Si todo el cuerpo fuera ojo, ¿dónde estaría el olfato?» La pregunta retórica resalta la necesidad de diversidad en el cuerpo de Cristo. Así como un cuerpo necesita múltiples sentidos para funcionar correctamente, la iglesia requiere dones espirituales variados. La mención del olfato subraya que incluso los sentidos aparentemente menores son esenciales para la integridad del conjunto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73494, 'spa', 'Lomos, cintura, caderas', 'La zona inferior del torso alrededor de la cintura y las caderas, abarcando tanto la parte literal del cuerpo que se ciñe para la preparación o el trabajo como la extensión metonímica al poder procreador y el linaje. Literalmente, los lomos se ciñen con un cinturón de cuero (Mt 3:4, Mc 1:6 sobre Juan el Bautista) o con la verdad como armadura espiritual (Ef 6:14), y se exhorta a los creyentes a ceñirlos en preparación (Lc 12:35, 1 P 1:13). Metonímicamente, representan la capacidad generativa y la descendencia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73498, 'spa', 'cuando, siempre que', 'Conjunción temporal-condicional formada por ὅτε + ἄν, que introduce eventos indefinidos, anticipados o recurrentes, no fijados en el pasado. Jesús la emplea para enmarcar acciones habituales — «cuando ores, cuando ayunes» (Mt 6:5-6, 16) — y momentos escatológicos futuros — «cuando el Hijo del Hombre venga en su gloria» (Mt 25:31). También rige verdades generales: «cuando el espíritu inmundo sale del hombre» (Mt 12:43).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73499, 'spa', 'cuando, al tiempo que', 'Adverbio relativo temporal que significa «cuando» o «en el momento en que», introduciendo cláusulas subordinadas que sitúan acciones en el tiempo. Rige típicamente verbos en indicativo para marcar eventos pasados puntuales («cuando Jesús terminó estas palabras», Mt 7:28; «cuando brotó la hierba», Mt 13:26). Se correlaciona con el demostrativo τότε («entonces»). Las traducciones emplean uniformemente conjunciones temporales básicas: spa «cuando», fra «quand», deu «als».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73500, 'spa', 'que (clausula de contenido)', 'El complementante declarativo ''que,'' introduciendo clausulas de contenido tras verbos de percepcion, cognicion y comunicacion. Es el sentido ampliamente dominante (mas de 880 ocurrencias), presente en frases como ''cuando Herodes vio que habia sido burlado'' (Mt 2:16) y ''no penseis que vine a abolir la Ley'' (Mt 5:17). El espanol ''que'' funciona como complementante dedicado en este uso.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73501, 'spa', 'porque, pues (causal)', 'La conjuncion causal ''porque,'' ''pues,'' ''ya que,'' introduciendo una razon o explicacion para lo precedente. Con 425 ocurrencias, es el segundo uso mas frecuente, prominente en las Bienaventuranzas (Mt 5:4-10), donde cada bendicion va seguida de hoti + causa: ''Bienaventurados los que lloran, porque ellos seran consolados.'' El espanol ''porque'' cumple esta funcion con precision.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73503, 'spa', 'lo que (relativo)', 'Una rara construccion pronominal relativa ho ti (relativo neutro ho + indefinido ti), que significa ''lo que'' o ''cualquier cosa que,'' a veces escrita como dos palabras en las ediciones criticas. Solo unas 5 ocurrencias claras se conservan, incluyendo el juramento de Herodes ''lo que me pidas'' (Mc 6:23), y la promesa ''cualquier cosa que pidais en mi nombre'' (Jn 14:13; 15:16).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73506, 'spa', 'Relativo indefinido temporal', 'Pronombre relativo indefinido (aqui en genitivo) que significa ''de quienquiera'', ''de cualquiera que'' o, en construcciones temporales, ''hasta que''. El compuesto ὅστις generaliza mas alla de un referente especifico hacia cualquier miembro de una clase. En las cinco apariciones neotestamentarias citadas, predomina el uso temporal: Mt 5:25 urge a la reconciliacion ''mientras'' se esta en el camino; Lc 12:50 expresa la urgencia de Jesus ''hasta que'' se cumpla su mision.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73507, 'spa', 'no (particula de negacion)', 'La particula de negacion objetiva empleada con verbos en modo indicativo y aserciones facticas, formando el complemento de me (negacion subjetiva/volitiva). En pasajes como Mt 5:14 (''una ciudad asentada sobre un monte no se puede esconder'') y Mt 1:25 (''no la conocio''), ou niega la realidad de manera tajante, sin expresar prohibicion. Todas las lenguas meta la traducen uniformemente: espanol ''no,'' frances ''ne...pas,'' aleman ''nicht.''');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73513, 'spa', 'Adverbio relativo de lugar que significa ''donde'' o ''en el cual,'' usado para intr', 'Adverbio relativo de lugar que significa ''donde'' o ''en el cual,'' usado para introducir cláusulas relativas que especifican ubicación. Aparece en la narrativa para situar acontecimientos: la estrella deteniéndose donde estaba el niño (Mt 2:9), los discípulos congregados donde Cristo está presente (Mt 18:20), y Jesús volviendo al pueblo donde creció (Lc 4:16). El español ''donde'' y ''adonde'' reflejan fielmente esta función locativa directa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73515, 'spa', 'Burla despectiva', 'Marcos 15:29 recoge el escarnio de la multitud: «¡Ah! Tú que destruirías el templo y lo reedificarías en tres días...» La interjección abre su mofa, un estallido agudo de desprecio. Lo que ellos pretenden como burla, el lector lo reconoce como trágica ironía: Jesús efectivamente levantará el templo de su cuerpo. Su escarnio apunta involuntariamente a la verdad de la resurrección.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73516, 'spa', '¡Ay! Exclamación de denuncia profética, lamento y advertencia, dirigida contra p', '¡Ay! Exclamación de denuncia profética, lamento y advertencia, dirigida contra personas, ciudades o conductas bajo juicio divino. Jesús pronuncia ayes contra las ciudades galileas impenitentes (Mt 11:21), contra la hipocresía farisaica en una fulminante serie de siete ayes (Mt 23:13-29) y contra el traidor (Mt 26:24). En Apocalipsis señala la catástrofe cósmica y los tres ayes escatológicos (Ap 8:13; 9:12; 11:14). Arraigada en la tradición profética hebrea del הוֹי/אוֹי, la interjección fusiona dolor personal y juicio divino en un solo grito.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73518, 'spa', 'Negación enfática', 'Mateo 2:6 cita al profeta: «Belén... de ningún modo eres la menor entre los gobernantes de Judá.» La negación enfática corrige cualquier noción de insignificancia. Aunque pequeña geográficamente, el papel de Belén como cuna del Mesías la eleva a una posición prominente. El adverbio subraya que lo aparentemente menor a ojos humanos posee importancia suprema en el plan redentor de Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73519, 'spa', 'ni, tampoco', 'Negación conjuntiva que une dos o más elementos negados: «ni», «y no», «tampoco». Continúa una negación previa para añadir otro elemento o cláusula excluida. Las traducciones interlingüísticas convergen estrechamente — spa «ni», fra «ni», deu «auch nicht» —, reflejando la función aditivo-negativa directa. Central en el argumento de Jesús desde la naturaleza en Mt 6:26 («no siembran, ni siegan») y en catálogos de negaciones acumuladas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73520, 'spa', 'ni siquiera, ni aun', 'Negación adverbial enfática que significa «ni siquiera» o «ni aun», intensificando la negación para destacar que incluso el caso menos esperado queda incluido en la exclusión. El español la distingue con «tampoco» y «ni aun» donde el sentido conjuntivo usa el simple «ni», confirmando la fuerza intensificada. Prominente en Mt 6:29 («ni aun Salomón») y Mt 27:14 (Jesús no respondió «ni una palabra»).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73532, 'spa', 'nadie, ninguno', 'Uso pronominal referido a personas: «nadie», «ninguno», «ni uno» — el sentido dominante con 207 apariciones, empleado tanto en posición de sujeto como de objeto. «Nadie conoce al Hijo sino el Padre» (Mt 11:27); «Nadie puede entrar en la casa del hombre fuerte» (Mc 3:27). El español nadie, el alemán niemand y el francés personne despliegan sus pronombres personales negativos dedicados. La negación absoluta no admite excepciones.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73536, 'spa', 'nada', 'Uso pronominal referido a cosas o abstracciones: «nada», «ninguna cosa» — 11 apariciones donde la forma neutra οὐδέν se refiere a cosas en lugar de personas. «Jesús callaba y nada respondió» (Mt 26:62-63); «Nada hay imposible para Dios» (Lc 1:37 variante). El español «nada» y el alemán «nichts» seleccionan pronombres negativos específicos para cosas, distinguiéndolo del pronominal personal «nadie».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73538, 'spa', 'ninguno, ningún', 'Uso adjetival o atributivo que modifica un sustantivo: «ninguno», «ningún», «ni un solo» — 16 apariciones donde οὐδείς funciona como adjetivo en lugar de pronombre independiente. «Ningún profeta es aceptado en su propia tierra» (Lc 4:24); «ninguna culpa hallo en él» (Jn 18:38). El español «ninguno/ninguna/ningún» y el alemán kein mapean fielmente esta función adjetival.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73557, 'spa', 'Adverbio enfático de negación temporal absoluta que significa ''en ningún momento', 'Adverbio enfático de negación temporal absoluta que significa ''en ningún momento, nunca jamás''. Refuerza la negación más allá de un simple ''no'', abarcando todo el tiempo. Jesús lo usa en sus declaraciones más solemnes: ''Nunca os conocí'' (Mt 7:23) y ''¿Nunca leísteis?'' como reproche retórico (Mt 21:16, 42). La promesa desmedida de Pedro, ''Nunca me apartaré'' (Mt 26:33), y la exclamación de la multitud, ''Nunca se vio algo así en Israel'' (Mt 9:33), muestran su fuerza irrestricta.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73558, 'spa', 'Todavia no', 'Todavia no, aun no: indica que un evento o estado esperado no se ha realizado hasta el momento presente. En Jn 7:39 el Espiritu ''todavia no'' habia sido dado, creando suspenso teologico respecto a la glorificacion. Jn 20:9 lo aplica a la comprension de los discipulos, y Jn 19:41 al sepulcro sin usar. La expresion espanola ''todavia no'' conserva la expectativa temporal propia del adverbio: lo que aun no es, se espera que llegue a ser.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73559, 'spa', 'ya no, nunca más', 'Adverbio temporal negativo que indica que una condición, acción o estado previamente existente ha llegado a su fin: «ya no», «nunca más», «no más». Estructuralmente presupone una realidad anterior ahora superada, lo que lo convierte en término clave para expresar la transformación teológica: los creyentes ya no son esclavos sino hijos (Gá 4:7), la muerte ya no tiene dominio sobre el Cristo resucitado (Ro 6:9).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73561, 'spa', 'Inferencia conclusiva', 'Juan 18:37 registra la respuesta de Pilato a Jesús: «¿Así que tú eres rey?» La partícula marca el intento de Pilato de clarificar la identidad de Jesús a partir de lo que acaba de escuchar. Transmite tanto progresión lógica («entonces esto debe significar...») como presión interrogativa. Pilato busca confirmación explícita, pasando de las declaraciones enigmáticas de Jesús a una pregunta directa que exige una respuesta clara.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73562, 'spa', 'por tanto, entonces', 'Conjunción inferencial y transicional que indica que la declaración siguiente es consecuencia, conclusión o continuación del discurso precedente. Funciona como secuenciador narrativo en los Evangelios (Mt 1:17 «de manera que todas las generaciones») y como conector lógico en las Epístolas (Ro 5:1 «justificados, pues, por la fe»). Las 505 apariciones expresan esta única función inferencial-transicional: spa «pues/por tanto», fra «donc», deu «nun».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73567, 'spa', 'Adverbio temporal negativo que significa «todavía no», indicando que un estado o', 'Adverbio temporal negativo que significa «todavía no», indicando que un estado o evento esperado aún no ha ocurrido pero se anticipa implícitamente. Jesús reprende a los discípulos: «¿Todavía no entendéis?» (Mt 16:9; Mc 8:17, 21). El discurso del Olivete advierte que «el fin aún no ha llegado» (Mt 24:6; Mc 13:7). En Juan adquiere precisión teológica: la hora de Jesús «aún no ha venido» (Jn 2:4; 7:30; 8:20), el Espíritu «aún no había sido dado» (Jn 7:39), y Hebreos señala que «todavía no vemos todas las cosas sujetas a él» (Heb 2:8).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73568, 'spa', 'Cola apocaliptica', 'Cola: el apendice posterior de una criatura, empleado en el NT exclusivamente en las visiones apocalipticas de Apocalipsis como instrumento de destruccion y poder. En Ap 9:10 las langostas demoniacas tienen colas de escorpion con aguijones que atormentan a la humanidad. Ap 9:19 describe caballos de guerra cuyas colas serpentinas poseen cabezas daninas. En Ap 12:4, la cola del dragon arrastra un tercio de las estrellas del cielo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73569, 'spa', 'Celestial, del cielo', 'Relativo al cielo como morada de Dios o ámbito de origen, usado adjetivalmente para calificar al Padre, su reino o las realidades asociadas con la esfera divina. Cada aparición en el NT (Mt 5:48, 6:14, 6:26, 6:32, 15:13, Lc 2:13) modifica un sustantivo vinculado a la actividad de Dios — Padre, plantío, ejército — de modo que la palabra funciona menos como descriptor cosmológico y más como marcador teológico de la procedencia y provisión divinas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73571, 'spa', 'cielo(s), rango completo', 'El espectro semántico completo de οὐρανός, que abarca tanto el cielo visible —firmamento, atmósfera, espacio sideral— como el ámbito trascendente donde mora Dios. En los Evangelios aparece como dominio de las aves (Mt 6:26), contraparte cósmica de la tierra (Mt 5:18) y sede de la autoridad y recompensa divinas (Mt 6:20). El español «cielos» refleja esta doble cobertura físico-divina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73576, 'spa', 'Nombre personal cristiano', 'Romanos 16:9 menciona a Urbano entre aquellos a quienes Pablo envía saludos, llamándolo ''nuestro colaborador en Cristo''. Este nombre personal, de origen latino, lo identifica como probable miembro de la comunidad cristiana en Roma. La designación de Pablo como ''colaborador'' lo sitúa entre quienes participaban activamente en el ministerio del evangelio, aunque no se conocen detalles específicos de su contribución.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73577, 'spa', 'Esposo de Betsabé', 'Mateo 1:6 identifica a Salomón como nacido ''de la que fue mujer de Urías'', refiriéndose a Betsabé sin nombrarla directamente. La formulación pone en primer plano el escándalo: la violación y el asesinato de Urías se perciben detrás del reinado de David. Incluir este detalle en la genealogía del Mesías señala que los propósitos redentores de Dios obran a través de seres humanos imperfectos e historias quebrantadas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73578, 'spa', 'Oído (parte del cuerpo)', 'Oído (parte del cuerpo). El órgano físico de la audición, empleado tanto para la parte literal del cuerpo como en sentido figurado para la percepción espiritual o su ausencia. En el plano literal, Pedro cortó la oreja del siervo del sumo sacerdote (Lc 22:50; Jn 18:10, 26) y el mensaje susurrado se proclama (Mt 10:27). El estribillo figurado «el que tiene oídos, oiga» (Mt 11:15; 13:9, 43; Mr 4:9, 23; Ap 2-3) convierte al oído en símbolo de la disposición del corazón. La acusación de Esteban de ser «incircuncisos de oídos» (Hch 7:51) recoge la tradición profética de Isaías 6:10.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73581, 'spa', 'ni (conjunción negativa)', 'Conjunción negativa correlativa que coordina elementos negados, apareciendo característicamente en pares οὔτε...οὔτε con el significado de «ni... ni». Estructura negaciones exhaustivas, desde la enseñanza de Jesús sobre el tesoro celestial inmune a polilla y óxido (Mt 6:20) hasta la solemne declaración paulina de que ni la muerte ni la vida ni cosa alguna creada puede separar del amor de Dios (Ro 8:38-39).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73584, 'spa', 'esto, estas cosas', 'Pronombre demostrativo que senala cosas, conceptos, situaciones o realidades abstractas: el uso neutro y general, el sentido mas frecuente con mas de 1.000 ocurrencias. Aparece en frases como διὰ τοῦτο (''por esto,'' Mt 6:25), μετὰ ταῦτα (''despues de estas cosas'') y ταῦτα πάντα (''todas estas cosas,'' Mt 6:33). Las traducciones convergen en demostrativos neutros: ''esto,'' ''ceci,'' ''dies.''');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73588, 'spa', 'este, esta persona', 'Pronombre demostrativo referido a personas concretas: ''este,'' ''esta,'' ''estos,'' ''estas.'' Empleado como sustantivo en formas masculinas y femeninas, identifica individuos dentro de la narracion. Mt 3:3 (''este es aquel de quien se hablo''), Mt 12:23 (''!sera este el Hijo de David?'') y Mt 11:10 ilustran la referencia personal. El espanol ''este/esta'' distingue genero de manera natural.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73596, 'spa', 'esto es, es decir', 'Un uso a nivel discursivo donde el demostrativo introduce una clausula explicativa o epexegetica, funcionando como ''esto es,'' ''es decir'' o ''a saber.'' La construccion τοῦτ᾽ ἔστιν aparece en Ro 9:8 (''esto es, no son los hijos de la carne''), Ro 10:6 y Mc 7:2 (''esto es, sin lavar''). Esta funcion metalinguistica es rara (unas 13 ocurrencias) pero reconocible en todas las lenguas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73613, 'spa', 'así, de este modo', 'Adverbio demostrativo de manera que significa «de este modo», «así» o «de tal manera», derivado del pronombre οὗτος. Funciona tanto anafóricamente (señalando hacia lo ya descrito) como catafóricamente (anticipando lo que sigue, a menudo emparejado con καθώς o ὥσπερ). Posee fuerza intensificadora en pasajes como Jn 3:16 («de tal manera amó Dios al mundo») y fuerza estructuradora en la enseñanza de Jesús (Mt 5:12, 16).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73618, 'spa', '¿acaso no? (negación retórica)', 'Partícula negativa intensificada (οὐ + χί) empleada en preguntas retóricas que anticipan una respuesta afirmativa, funcionando como apelación al acuerdo más que como verdadera negación. Jesús la usa repetidamente en el Sermón del Monte para cuestionar una ética minimalista (Mt 5:46-47, «¿no hacen lo mismo los publicanos?») y para argumentar de menor a mayor (Mt 6:25-26, «¿no es la vida más que el alimento?»).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73625, 'spa', 'Deudor, el que debe', 'Persona que tiene una deuda, ya sea financiera o moral/espiritual, y que por tanto está bajo obligación. El NT aprovecha la superposición entre deuda literal y figurada con gran efecto teológico. En Mt 6:12 Jesús enseña a orar pidiendo perdón mediante lenguaje de deuda, y en Mt 18:24 la enorme deuda de la parábola (diez mil talentos) ilustra la magnitud infinita del perdón divino.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73628, 'spa', 'Deuda u obligación', 'La evidencia interlingüística muestra tanto la deuda financiera concreta como el deber abstracto: español «deuda/deudas», francés «dette», alemán «Schulden». El léxico distingue la deuda monetaria (sentido primario) de «lo debido» (obligación moral). Mt 18:32 la usa para la deuda perdonada por el rey, Ro 13:7 enfatiza las obligaciones cívicas y 1 Co 7:3 la aplica al deber conyugal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73630, 'spa', 'Deber, estar moralmente obligado', 'Deber, estar moralmente obligado. Obligación moral o ética: estar obligado por deber, ser lo apropiado o necesario. Es el sentido predominante en el NT (25 de 35 apariciones), referido a lo que uno debe hacer ante Dios o el prójimo. Jesús enseña «somos siervos inútiles; hicimos lo que debíamos hacer» (Lc 17:10), y en el aposento alto declara que «debéis lavaros los pies unos a otros» (Jn 13:14). La exhortación apostólica lo emplea constantemente (1 Jn 4:11; 3 Jn 1:8).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73633, 'spa', 'Adeudar, deber una deuda', 'Adeudar, deber una deuda. Endeudamiento financiero: deber dinero, bienes o una deuda cuantificable. Se concentra en las parábolas de Mt 18:28-34 (los dos deudores) y Lc 7:41 (el prestamista). Los contextos parabólicos hacen explícitas las cantidades (''cien denarios,'' ''quinientos denarios''), confirmando la lectura económica concreta. También en Ro 13:8 «no debáis a nadie nada» y Flm 1:18.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73644, 'spa', 'Deseo optativo intenso', '¡Ojalá!, ¡quién pudiera! — exclamación optativa que expresa un deseo vehemente por algo improbable o no realizado. Pablo la usa retóricamente en 1 Co 4:8 (deseo irónico), 2 Co 11:1 (súplica de tolerancia) y Gá 5:12 (deseo chocante sobre los judaizantes). En Ap 3:15 Cristo añade patetismo divino. El español ''ojalá'' reproduce perfectamente el modo optativo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73645, 'spa', 'Provecho o ventaja', 'Las traducciones lo vierten consistentemente como «provecho» o «ventaja»: español «provecho», francés «avantage», alemán «Nutzen». El léxico lo remonta al homérico «ayuda, ventaja» (ὀφέλλω). Las tres apariciones neotestamentarias son preguntas retóricas que indagan el beneficio real frente al ilusorio: Pablo cuestiona el provecho de vivir sin esperanza de resurrección (1 Co 15:32) y Santiago desafía la utilidad de una fe sin obras (Stg 2:14, 16).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73647, 'spa', 'ojo(s), órgano de la vista', 'El órgano físico de la vista, usado literalmente para ver y para la ceguera (Mt 9:29-30; Jn 9:10-11) y figuradamente como lente de la condición moral y espiritual de la persona. La enseñanza de Jesús de que «el ojo es la lámpara del cuerpo» (Mt 6:22-23) hace del ojo un barómetro de luz u oscuridad interior. Pablo extiende la metáfora a la percepción espiritual —«los ojos de vuestro corazón» (Ef 1:18)— y el modismo semítico del «ojo malo» señala envidia o avaricia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73653, 'spa', 'Serpiente o culebra, abarcando tanto el reptil literal como toda su rica carga s', 'Serpiente o culebra, abarcando tanto el reptil literal como toda su rica carga simbólica. Se refiere a serpientes reales que pueden ser tomadas o que muerden (Mc 16:18; Lc 10:19; 1 Co 10:9), a la cualidad de astucia que Jesús recomienda a sus discípulos (Mt 10:16, «astutos como serpientes»), al tentador del Génesis cuyo engaño Pablo evoca (2 Co 11:3), y a la «serpiente antigua» identificada con Satanás en el Apocalipsis (Ap 12:9; 20:2). Los fariseos reciben el epíteto fulminante «serpientes, generación de víboras» (Mt 23:33).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73656, 'spa', 'Borde escarpado de monte', 'Lucas 4:29 relata cómo la multitud de la sinagoga de Nazaret, enfurecida por el sermón de Jesús, lo llevó hasta ''la ceja del monte'' para despeñarlo. La palabra captura ese borde peligroso donde el suelo firme da paso al vacío. La intención de matarlo empujándolo desde este precipicio subraya el impulso homicida provocado por sus declaraciones sobre los profetas y los gentiles.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73657, 'spa', 'Atormentado por espíritus', 'Hechos 5:16 relata cómo las multitudes traían enfermos y ''atormentados por espíritus inmundos'', todos los cuales fueron sanados. El participio describe una aflicción continua, un estado sostenido de tormento impuesto por poderes demoníacos. El contexto resalta el contraste: lo que los espíritus malignos perturban y desordenan, el ministerio apostólico lo restaura a la plenitud y la paz mediante la autoridad de Cristo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73658, 'spa', 'Amotinar una turba', 'Hechos 17:5 describe cómo judíos celosos en Tesalónica, reclutando ''algunos hombres malos de la plaza'', ''formaron un tumulto'' para alborotar la ciudad. El verbo enfatiza la intencionalidad: no fue indignación pública espontánea sino ira fabricada. Al reunir una turba a sueldo, los opositores convirtieron el desorden civil en arma para silenciar el evangelio, demostrando cuán fácilmente las multitudes pueden ser manipuladas con fines políticos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73659, 'spa', 'multitud, muchedumbre', 'Una reunión de personas vista como masa y no como cuerpo organizado: la multitud, la muchedumbre, el gentío. En los Evangelios, el ὄχλος es el público popular siempre presente en torno a Jesús, atraído por milagros y enseñanzas (Mt 14:5; Mr 2:4). El término conserva un leve matiz social del griego clásico (turba frente a ciudadanía) que aflora en pasajes como Jn 7:49. El español multitud y el francés foule preservan ambos registros.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73665, 'spa', 'Fortaleza ideológica', '2 Corintios 10:4 declara que las armas de nuestra milicia son poderosas para ''destruir fortalezas,'' refiriéndose no a fortificaciones físicas sino a argumentos que se oponen a Dios. Pablo presenta la mente como campo de batalla donde ideologías falsas erigen murallas. Solo el poder divino puede quebrantarlas, liberando pensamientos cautivos para obedecer a Cristo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73666, 'spa', 'Pescadito preparado', 'Pescado pequeño o preparado — diminutivo que denota el pez como alimento, especialmente como acompañamiento del pan. A diferencia de ἰχθύς (pez vivo), ὀψάριον subraya la dimensión culinaria. Juan lo emplea en la multiplicación (Jn 6:9, 11) y en el desayuno de la resurrección junto al mar de Tiberíades (Jn 21:9-13).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73667, 'spa', 'Tarde o atardecer', 'Tarde, al anochecer — indica la parte final de un día o un intervalo transcurrido. En Mc 11:11 y 11:19 Jesús sale del templo ''al caer la tarde''; Mc 13:35 lo enumera entre las vigilias. Mt 28:1 es célebremente ambiguo: ¿significa ὀψὲ σαββάτων ''tarde del sábado'' o ''después del sábado''? Una crux clásica de la cronología neotestamentaria.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73668, 'spa', 'Lluvia tardía', 'Santiago 5:7 alienta a la paciencia ''hasta la venida del Señor,'' usando al labrador que espera ''la lluvia temprana y la tardía'' como analogía. La lluvia tardía representa el ingrediente final antes de la cosecha. Así como el labrador no puede apresurar la lluvia, los creyentes aguardan el regreso de Cristo confiando en los tiempos de Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73669, 'spa', 'Atardecer — la porción final del día, que abarca desde la media tarde hasta la p', 'Atardecer — la porción final del día, que abarca desde la media tarde hasta la puesta del sol y las primeras horas de la noche. Funciona principalmente como marcador temporal narrativo en los Evangelios: escenas de sanación (Mt 8:16; Mc 1:32), los milagros de la multiplicación (Mt 14:15, 23; Mc 6:47), la observación del tiempo (Mt 16:2), el pago de los jornaleros al final del día (Mt 20:8), la Última Cena (Mt 26:20; Mc 14:17) y la sepultura de Jesús (Mt 27:57; Mc 15:42). El cómputo judío reconocía dos «tardes» — una en la tarde declinante y otra al ponerse el sol — lo que explica que Mateo pueda mencionar la tarde dos veces en un mismo relato (Mt 14:15 y 14:23).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73671, 'spa', 'Apariencia o rostro', 'Las traducciones multilingües destacan tanto la apariencia general como el rostro específico: español «apariencia/rostro», francés «visage», alemán «Angesicht». El léxico distingue entre «aspecto objetivo» y «semblante/rostro», aunque ambos derivan de la raíz de ver (ὄπωπα). Jn 7:24 advierte contra juzgar por la apariencia, Jn 11:44 describe el paño sobre el rostro de Lázaro, y Ap 1:16 retrata el semblante resplandeciente de Cristo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73672, 'spa', 'Paga o soldada', 'Paga, salario — dinero o provisiones por un servicio, especialmente la soldada militar, extendido metafóricamente a consecuencias merecidas. Lc 3:14 lo usa del sueldo de los soldados; 1 Co 9:7 del sustento militar. La metáfora de Ro 6:23 presenta la muerte como ''paga'' del pecado: retribución ganada e ineludible. En 2 Co 11:8 Pablo lo aplica al sustento ministerial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73673, 'spa', 'Atrapar con engaño', 'Mateo 22:15 relata que los fariseos deliberaron ''cómo atrapar'' a Jesús en sus palabras. La conspiración antes de preguntar sobre el tributo al César revela intención maliciosa. Fabrican un dilema donde cualquier respuesta podría ser usada en su contra. El verbo expone sus corazones: se acercan como cazadores, no como buscadores de verdad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73674, 'spa', 'Lazo o trampa', 'Lazo o trampa — dispositivo para atrapar presas desprevenidas, usado solo metafóricamente en el NT para peligros espirituales ocultos. De πήγνυμι (fijar), evoca algo tendido y al acecho. Lc 21:35 advierte que el día vendrá ''como un lazo''; Ro 11:9 lo aplica al endurecimiento de Israel. Las Pastorales alertan del ''lazo del diablo'' (1 Ti 3:7; 2 Ti 2:26).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73675, 'spa', 'Sufrimiento, aflicción o penalidad soportada, especialmente en conexión con la p', 'Sufrimiento, aflicción o penalidad soportada, especialmente en conexión con la pasión de Cristo y la participación del creyente en ella. Este es el uso predominante en el NT, con catorce apariciones. La teología paulina del sufrimiento impulsa la mayoría de los casos: ''los sufrimientos de Cristo abundan en nosotros'' (2 Co 1:5), ''la comunión de sus padecimientos'' (Fil 3:10) y ''los padecimientos del tiempo presente'' (Ro 8:18).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73677, 'spa', 'Pasión pecaminosa, deseo o impulso que opera dentro del cuerpo humano, arrastran', 'Pasión pecaminosa, deseo o impulso que opera dentro del cuerpo humano, arrastrando hacia el pecado. Solo dos apariciones claras en el NT: Ro 7:5 (''las pasiones de los pecados que actuaban por medio de la ley obraban en nuestros miembros'') y Gá 5:24 (''los que son de Cristo Jesús han crucificado la carne con sus pasiones y deseos''). El desplazamiento semántico del sufrimiento externo al impulso pecaminoso interno es notable.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73680, 'spa', 'Sujeto al padecimiento', 'Hechos 26:23 recoge a Pablo explicando ''que el Cristo había de padecer,'' describiendo la capacidad de sufrimiento del Mesías. Contra las expectativas de un rey impasible, Pablo insiste en que las Escrituras predijeron un siervo sufriente. El escándalo de la encarnación exige que el Ungido sea vulnerable, sienta dolor y muera — capacidades inherentes a la humanidad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73681, 'spa', 'Pasiones desordenadas', 'La evidencia multilingüe apunta consistentemente a pasiones intensas y negativas. El léxico traza el desarrollo semántico de ''lo que le sucede a uno'' a ''experiencia'' y luego a ''pasión/emoción'', frecuentemente con connotación negativa. Los tres usos neotestamentarios aparecen en contextos de deseo pecaminoso: pasiones degradantes (Ro 1:26), concupiscencia terrenal (Col 3:5) y lujuria pagana (1 Ts 4:5).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73682, 'spa', 'Guardián y tutor', 'Las traducciones multilingües preservan tanto el aspecto de custodia como el educativo. El léxico define al pedagogo como el ''esclavo que acompañaba al niño de casa a la escuela y de regreso'', distinto del maestro propiamente dicho (διδάσκαλος). Pablo lo usa metafóricamente en 1 Co 4:15 para guías espirituales y en Gá 3:24-25 para la ley como custodio temporal hasta Cristo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73683, 'spa', 'Niño pequeño', 'Juan 6:9 presenta ''un muchachito que tiene cinco panes de cebada y dos peces,'' destacando la insuficiencia de tales provisiones para una multitud. El diminutivo subraya el pequeño tamaño del niño y la escasez de la comida. La pregunta de Andrés — ''¿qué es esto para tantos?'' — prepara el milagro: Jesús toma lo insuficiente y lo convierte en abundancia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73684, 'spa', 'Disciplina correctiva', 'Disciplina correctiva o castigo formativo, especialmente de parte de Dios como padre amoroso. Hebreos 12 (vv. 5, 7, 8, 11) se apoya en Proverbios 3:11-12 para presentar la disciplina divina como dolorosa pero con propósito: «el Señor disciplina al que ama». Efesios 6:4 empareja παιδεία con νουθεσία (amonestación) en la crianza de los hijos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73686, 'spa', 'Instrucción formativa', 'Instrucción positiva o formación orientada al crecimiento moral y espiritual. En 2 Tim 3:16, la Escritura se describe como útil «para la instrucción en justicia» (παιδεία ἐν δικαιοσύνῃ), donde el énfasis recae en la educación constructiva más que en el castigo correctivo. Este matiz pedagógico y edificante complementa el sentido más severo de la disciplina correctiva.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73688, 'spa', 'Disciplina o castigo correctivo — castigo destinado a reformar, no meramente a p', 'Disciplina o castigo correctivo — castigo destinado a reformar, no meramente a penalizar. Este sentido predomina cuando Dios o figuras de autoridad infligen sufrimiento para el beneficio moral del receptor. Hebreos 12:6-7 presenta la disciplina divina como prueba de filiación: «al que el Señor ama, disciplina». En 1 Corintios 11:32, los corintios «son disciplinados por el Señor para que no sean condenados». Lucas 23:16 registra la propuesta de Pilato de «castigar» a Jesús y soltarlo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73693, 'spa', 'Formación, educación o instrucción — la configuración pedagógica del conocimient', 'Formación, educación o instrucción — la configuración pedagógica del conocimiento, el carácter o la conducta de una persona. Moisés fue «instruido» (ἐπαιδεύθη) en toda la sabiduría de los egipcios (Hch 7:22), y Pablo fue «formado» (πεπαιδευμένος) a los pies de Gamaliel (Hch 22:3). En 2 Timoteo 2:25, el siervo del Señor debe «instruir» con mansedumbre a los opositores. Tito 2:12 personifica la gracia como maestra que nos «educa» para vivir con piedad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73699, 'spa', 'Desde la niñez', 'Marcos 9:21 recoge el angustiado relato de un padre: el espíritu ha afligido a su hijo ''desde la niñez'', arrojándolo al fuego y al agua para destruirlo. El adverbio intensifica la tragedia: no es una crisis nueva sino un tormento crónico que se remonta a los primeros años del muchacho. La desesperación del padre nace en parte de la agotadora duración de la aflicción de su hijo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73700, 'spa', 'niño, criatura, infante', 'Niño pequeño, infante o criatura, que expresa el sentido diminutivo y afectuoso de παῖς. Destaca en los Evangelios para referirse al niño Jesús a quien los magos buscaron y Herodes persiguió (Mt 2:8-14), a los niños que Jesús abrazó como modelo de entrada al reino (Mt 18:2-5; 19:13-14) y a los recién nacidos en Juan 16:21. El matiz tierno y diminutivo distingue este término del más general τέκνον.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73707, 'spa', 'Joven sirvienta, criada o esclava en un hogar doméstico', 'Joven sirvienta, criada o esclava en un hogar doméstico. La palabra aparece de forma prominente en las escenas de la negación de Pedro, donde una criada lo identifica como seguidor de Jesús (Mt 26:69; Mc 14:66, 69; Lc 22:56; Jn 18:17), en la alegoría paulina de Agar y Sara que distingue a la esclava de la mujer libre (Gá 4:22-31), y en el relato de Rode, la criada que responde a la puerta cuando Pedro llega tras su milagrosa liberación de la cárcel (Hch 12:13). Derivado de παῖς (''niño, siervo''), el término subraya tanto la condición femenina como el estatus servil.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73711, 'spa', 'Jolgorio idolátrico', '1 Corintios 10:7 advierte contra la idolatría citando el incidente del becerro de oro: ''se sentaron a comer y a beber, y se levantaron a jugar''. El verbo capta el jolgorio festivo que acompañaba la falsa adoración: danzas, celebración y posiblemente inmoralidad sexual. Pablo lo usa para mostrar cuán rápido la adoración al Dios verdadero puede degenerar en placer autoindulgente cuando el corazón se vuelve hacia los ídolos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73712, 'spa', 'Siervo, criado o esclavo; alguien que sirve a un amo humano o, en uso teológico,', 'Siervo, criado o esclavo; alguien que sirve a un amo humano o, en uso teológico, el siervo escogido de Dios. El siervo paralítico del centurión (Mt 8:6, 8, 13) y los criados de Herodes (Mt 14:2) ilustran el rol social. De manera significativa, Mateo 12:18 aplica el título a Jesús como siervo de Dios, citando a Isaías, convirtiendo la subordinación social en una categoría cristológica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73713, 'spa', 'Niño, muchacho o muchacha; una persona joven identificada por su edad y no por s', 'Niño, muchacho o muchacha; una persona joven identificada por su edad y no por su función social. La masacre de Herodes tiene como objetivo a los niños varones de dos años para abajo (Mt 2:16). Jesús sana a un muchacho epiléptico (Mt 17:18) y los niños gritan Hosanna en el templo (Mt 21:15). A Jesús a los doce años se le llama παῖς (Lc 2:43), al igual que a la hija de Jairo (Lc 8:51).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73720, 'spa', 'Golpear o herir', 'Golpear o herir: asestar un golpe fisico con la mano, un arma o un aguijon. El verbo implica contacto directo y violento. Tres de los cinco usos neotestamentarios aparecen en la narrativa de la Pasion: Mt 26:68 y Lc 22:64 describen el reto burlesco al Jesus vendado (''Quien te golpeo?''), mientras que Mc 14:47 y Jn 18:10 registran el golpe de espada contra la oreja del siervo del sumo sacerdote. Ap 9:5 lo aplica al aguijon de las langostas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73721, 'spa', 'Hace mucho tiempo', 'Hace mucho tiempo, antiguamente: marcador temporal que señala al pasado distante, frecuentemente empleado en comparaciones entre realidades pasadas y presentes. En los Evangelios intensifica el reproche: Tiro y Sidón se habrían arrepentido ''hace mucho'' (Mt 11:21; Lc 10:13). En Hebreos 1:1 agrupa toda la era profética en un solo ''antiguamente'', contrastándola con la palabra definitiva del Hijo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73725, 'spa', 'Viejo, antiguo o perteneciente a una era pasada, generalmente puesto en contrast', 'Viejo, antiguo o perteneciente a una era pasada, generalmente puesto en contraste con lo nuevo (καινός/νέος). Se aplica a objetos materiales desgastados como vestidos viejos y odres que no resisten el vino nuevo (Mt 9:16-17; Mr 2:21-22; Lc 5:36-39), a la ''vieja levadura'' del pecado que debe eliminarse en la Pascua (1 Co 5:7-8), al ''viejo hombre'' crucificado con Cristo en la teología bautismal (Ro 6:6; Ef 4:22; Col 3:9) y al ''mandamiento antiguo'' de 1 Jn 2:7.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73730, 'spa', 'Obsolescencia del pacto', 'Romanos 7:6 contrasta dos modos de servicio: servimos ''en la novedad del Espíritu y no en la vejez de la letra''. El sustantivo caracteriza al antiguo pacto como obsoleto, con su función cumplida y superada. Pablo no desprecia la ley, pero reconoce que su era ha terminado. El Espíritu trae vitalidad renovada donde la letra solo traía condenación anticuada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73731, 'spa', 'Envejecer o desgastar', 'Hacer viejo, desgastar o volver obsoleto: causar que algo envejezca, se deteriore o pierda su vigencia por el paso del tiempo o por reemplazo divino. Lc 12:33 lo usa para bolsas que no se desgastan, contrastando la permanencia celestial con la decadencia terrenal. Heb 1:11 lo aplica cosmicamente a los cielos que se desgastaran. La carga teologica mas fuerte aparece en Heb 8:13, donde el anuncio divino de un pacto nuevo convierte al primero en caduco.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73732, 'spa', 'Lucha espiritual', 'Efesios 6:12 declara: ''Nuestra lucha no es contra carne y sangre'', empleando este término atlético para el conflicto espiritual del cristiano. La metáfora de la lucha libre enfatiza la cercanía e intensidad del combate: no escaramuzas a distancia sino un forcejeo íntimo con fuerzas espirituales. Pablo advierte que los verdaderos adversarios no son humanos sino potestades cósmicas de las tinieblas, que requieren armas diferentes a las físicas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73734, 'spa', 'de nuevo, otra vez', 'Adverbio que indica repetición, retorno o reanudación de una acción: «de vuelta» o «una vez más». En el Nuevo Testamento señala con mayor frecuencia la recurrencia de un acontecimiento o la reanudación del discurso: «otra vez le llevó el diablo a un monte muy alto» (Mt 4:8), «también el reino de los cielos es semejante a...» (Mt 13:45). Puede indicar asimismo reversión a un estado anterior (Gá 4:9, «volver de nuevo a los débiles elementos»).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73735, 'spa', 'Clamor colectivo unánime', 'Apareciendo una sola vez en el Nuevo Testamento, este término capta el grito colectivo de toda la multitud ante Pilato exigiendo la crucifixión de Jesús. Las glosas multilingües (''todos juntos'', ''tous ensemble'', ''all together'') preservan consistentemente la naturaleza corporativa y simultánea de este trágico momento, distinguiéndolo de clamores individuales o respuestas sucesivas. Este hapax legomenon marca uno de los momentos más solemnes de la narrativa de la Pasión.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73736, 'spa', 'Provincia de Panfilia', 'Panfilia: provincia romana en la costa meridional de Asia Menor, entre los montes Tauro y el mar Mediterraneo. Su nombre probablemente deriva del griego que significa ''de toda tribu'' (πᾶν + φυλή), reflejando su poblacion mixta. En el NT aparece exclusivamente en Hechos como punto recurrente en la historia de la iglesia primitiva: judios panfilios presencian Pentecostes (Hch 2:10), Pablo entra en la region en su primer viaje misionero y su barco pasa frente a ella rumbo a Roma.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73737, 'spa', 'Mesón o posada', 'Lucas 10:34 describe al samaritano llevando al hombre herido a ''un mesón'' y pagando al mesonero para que lo cuidara. La posada pública se convierte en lugar de recuperación y seguridad tras la violencia sufrida en el camino. Que el samaritano lleve a la víctima a un establecimiento comercial en vez de a su propia casa no disminuye su compasión, sino que demuestra sabiduría práctica y provisión generosa para un cuidado continuo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73738, 'spa', 'Mesonero o posadero', 'Lucas 10:35 menciona al samaritano entregando dinero al ''mesonero'', encargándole que cuide al herido y prometiendo reembolsar cualquier gasto adicional. El mesonero se convierte en agente de la compasión continua del samaritano. La parábola de Jesús confía en que este personaje comercial cumplirá el acuerdo, sugiriendo que el amor al prójimo puede integrar incluso las transacciones de negocio en propósitos redentores.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73739, 'spa', 'Asamblea festiva celestial', 'Hebreos 12:23 describe a los creyentes llegando ''a la asamblea festiva y congregación de los primogénitos inscritos en el cielo''. El sustantivo captura la naturaleza gozosa y celebratoria de la realidad celestial, no un deber sombrío sino adoración festiva. El autor presenta la salvación no como el ingreso a un espacio silencioso y solemne, sino como la incorporación a una celebración continua, una fiesta cósmica de la humanidad redimida adorando ante el trono de Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73740, 'spa', 'Con toda la casa', 'Hechos 16:34 relata que el carcelero ''se regocijó con toda su casa de haber creído en Dios''. El adverbio indica que toda la unidad doméstica participó en la conversión y el bautismo. No fue una decisión solitaria que dejara a la familia dividida, sino un giro corporativo hacia Cristo. El gozo unido del hogar refleja el poder del evangelio para transformar unidades sociales enteras, no solo individuos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73741, 'spa', 'Armadura completa', 'Todas las traducciones mantienen el concepto de armadura íntegra. El léxico la define como la ''armadura del ὁπλίτης'' (infantería pesada), enumerando todos sus componentes: escudo, casco, coraza, grebas, espada y lanza. Lucas 11:22 la usa literalmente para el equipo de un hombre fuerte, mientras que Efesios 6:11, 13 la emplea metafóricamente para la armadura espiritual del creyente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73742, 'spa', 'Astucia enganosa', 'Astucia o artimania: sagacidad inescrupulosa empleada para enganar o manipular. Etimologicamente derivada de πανοῦργος (''dispuesto a hacer cualquier cosa''), la palabra implica flexibilidad moral al servicio del interes propio. Lc 20:23 muestra a Jesus detectando la πανουργία detras de la trampa del tributo. Pablo en 1 Co 3:19 invierte la situacion citando Job 5:13: Dios atrapa a los sabios del mundo en su propia astucia. En 2 Co 11:3, Pablo teme que la serpiente extravie a los creyentes con esa misma artimania.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73743, 'spa', 'Astuto o taimado', '2 Corintios 12:16 cita la acusación de los oponentes de Pablo: ''siendo astuto, os atrapé con engaño''. El adjetivo aparece en un cargo que Pablo rechaza: que su aparente renuncia al sustento ocultaba un plan para explotarlos mediante la colecta. La palabra sugiere astucia manipuladora, el tipo de cálculo mañoso que usa la aparente generosidad para encubrir el interés propio. Pablo niega la acusación mientras la vuelve en su contra.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73744, 'spa', 'En todas partes', 'En todo lugar, por todas partes — expresión de extensión espacial universal. Se usa para describir la difusión de la reputación de Jesús por toda Galilea (Mc 1:28), la actividad de los discípulos sanando y predicando en cada aldea (Lc 9:6, Mc 16:20), y la proclamación universal de Pablo de que Dios manda el arrepentimiento en todas partes (Hch 17:30). En Hechos 21:28, los oponentes de Pablo lo acusan de enseñar a todos «en todas partes» contra la ley.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73747, 'spa', 'En toda manera', 'En Acts 24:3, el orador Tértulo dice: ''de toda manera... lo reconocemos con toda gratitud''. El adverbio funciona retóricamente para intensificar la adulación dirigida a Félix: no solo de algunas maneras o a veces, sino de forma exhaustiva y universal. El tono servil del discurso emplea este lenguaje totalizador para ganarse su favor antes de lanzar acusaciones contra Pablo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73748, 'spa', 'Desde todas partes', 'La evidencia multilingüe subraya la dirección universal. El léxico señala la raíz πᾶς (''todo'') y rastrea su uso desde Homero. Marcos 1:45 describe a la gente acudiendo ''de todas partes'' a Jesús, Lucas 19:43 profetiza que los enemigos rodearán Jerusalén ''por todos lados'', y Hebreos 9:4 indica un recubrimiento de oro total sobre el arca.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73749, 'spa', 'Todopoderoso, Soberano absoluto', 'Todopoderoso, Soberano absoluto. Titulo divino que significa ''Todopoderoso'' o ''Soberano de todo'', que atribuye a Dios dominio y poder ilimitados sobre toda la creacion. Usado casi exclusivamente como epiteto liturgico y doxologico en Apocalipsis (1:8; 4:8; 11:17; 15:3; 16:7,14; 19:6,15; 21:22), donde puntua la adoracion celestial y anuncia el juicio escatologico. El unico uso paulino (2 Corintios 6:18) cita 2 Samuel 7:8 LXX. Traduce los titulos hebreos El Shaddai y YHWH Tsevaoth.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73750, 'spa', 'Siempre, en todo tiempo', 'Siempre, en todo tiempo. Expresa continuidad ininterrumpida o hábito constante. Jesús lo emplea para realidades permanentes («a los pobres siempre los tendréis,» Mt 26:11), mientras Pablo lo usa para la actitud ideal del creyente («estad siempre gozosos,» 2 Co 6:10; «orando siempre,» 1 Ts 1:2). Su fuerza abarca desde el sentido literal ''en todo momento'' hasta el práctico ''habitualmente, de manera constante.''');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73751, 'spa', 'Ciertamente, sin duda', 'Afirmación enfática: «ciertamente», «seguramente», «por todos los medios». Refuerza aseveraciones, expectativas confiadas o intenciones resueltas. En Lucas 4:23 Jesús anticipa que la multitud «seguramente» citará el proverbio; en Hechos 28:4 los isleños concluyen que la víctima de la mordedura de serpiente es «ciertamente» un asesino. El uso en 1 Corintios 9:10 confirma este valor de certeza absoluta.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (73753, 'spa', 'De ninguna manera', 'Usado con negación para expresar rechazo total o negación enfática: «de ninguna manera», «en absoluto». En Romanos 3:9 Pablo pregunta si los judíos tienen alguna ventaja y responde «de ninguna manera» (οὐ πάντως). De igual modo, en 1 Corintios 16:12, Apolos «de ninguna manera» estaba dispuesto a ir en ese momento. La misma palabra que afirma todo puede, con una negación, negarlo absolutamente.');